package com.example.simpleaccountant.ui.suppliers;import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.model.Supplier;import java.util.*;
public class SupplierAdapter extends RecyclerView.Adapter<SupplierAdapter.VH>{public interface Listener{void onDelete(Supplier s);}private List<Supplier> items=new ArrayList<>();private final Listener l;public SupplierAdapter(Listener l){this.l=l;}public void setItems(List<Supplier> x){items=x;notifyDataSetChanged();}@NonNull @Override public VH onCreateViewHolder(@NonNull ViewGroup p,int v){return new VH(LayoutInflater.from(p.getContext()).inflate(R.layout.item_simple,p,false));}@Override public void onBindViewHolder(@NonNull VH h,int i){Supplier s=items.get(i);h.t1.setText(s.getName());h.t2.setText(s.getPhone());h.del.setOnClickListener(v->l.onDelete(s));}@Override public int getItemCount(){return items.size();}static class VH extends RecyclerView.ViewHolder{TextView t1,t2;ImageButton del;VH(View v){super(v);t1=v.findViewById(R.id.t1);t2=v.findViewById(R.id.t2);del=v.findViewById(R.id.btnDelete);}}}
